      out.write("        galleryData = rawGallery ? JSON.parse(rawGallery) : [];\r\n");
      out.write("    } catch (e) { galleryData = []; }\r\n");
      out.write("\r\n");
      out.write("    // Đảm bảo có dữ liệu mẫu nếu rỗng\r\n");
      out.write("    if (!coreValuesData || coreValuesData.length === 0) {\r\n");
      out.write("        coreValuesData = [\r\n");
      out.write("            { icon: \"bi-star\", title: \"Chất lượng vượt trội\", desc: \"Luôn đặt chuẩn mực cao nhất trong từng sản phẩm và dịch vụ.\" },\r\n");
      out.write("            { icon: \"bi-lightbulb\", title: \"Đổi mới sáng tạo\", desc: \"Khuyến khích tư duy mới, không ngừng thử nghiệm và bứt phá.\" },\r\n");
      out.write("            { icon: \"bi-shield-check\", title: \"Chính trực & Minh bạch\", desc: \"Minh bạch trong mọi quy trình và tôn trọng cam kết với nhân sự.\" }\r\n");
      out.write("        ];\r\n");
      out.write("    }\r\n");
      out.write("\r\n");
      out.write("    if (!perksData || perksData.length === 0) {\r\n");
      out.write("        perksData = [\r\n");
      out.write("            { icon: \"bi-cash-coin\", title: \"Lương & Thưởng cạnh tranh\", desc: \"Thu nhập hấp dẫn cùng thưởng hiệu quả dự án xứng đáng.\" },\r\n");
      out.write("            { icon: \"bi-heart-pulse\", title: \"Bảo hiểm sức khỏe cao cấp\", desc: \"Chăm sóc y tế toàn diện cho bản thân và người thân.\" },\r\n");
      out.write("            { icon: \"bi-laptop\", title: \"Trang thiết bị hiện đại\", desc: \"Macbook/Laptop cấu hình cao đáp ứng tối ưu công việc.\" }\r\n");
      out.write("        ];\r\n");
