      out.write("            \"https://images.unsplash.com/photo-1522071820081-009f0129c71c?auto=format&fit=crop&w=800&q=80\",\r\n");
      out.write("            \"https://images.unsplash.com/photo-1497366216548-37526070297c?auto=format&fit=crop&w=800&q=80\",\r\n");
      out.write("            \"https://images.unsplash.com/photo-1517245386807-bb43f82c33c4?auto=format&fit=crop&w=800&q=80\"\r\n");
      out.write("        ];\r\n");
      out.write("    }\r\n");
      out.write("\r\n");
      out.write("    renderCoreValuesList();\r\n");
      out.write("    renderPerksList();\r\n");
      out.write("    renderGalleryList();\r\n");
      out.write("    bindRealTimeMiniPreview();\r\n");
      out.write("});\r\n");
      out.write("\r\n");
      out.write("// Render danh sách Giá trị cốt lõi\r\n");
      out.write("function renderCoreValuesList() {\r\n");
      out.write("    const container = document.getElementById('coreValuesContainer');\r\n");
      out.write("    container.innerHTML = '';\r\n");
      out.write("    coreValuesData.forEach((item, idx) => {\r\n");
      out.write("        const iconVal = item.icon || 'bi-star';\r\n");
      out.write("        const titleVal = item.title || '';\r\n");
      out.write("        const descVal = item.desc || '';\r\n");
      out.write("        const div = document.createElement('div');\r\n");
      out.write("        div.className = 'border rounded p-2 bg-light d-flex align-items-center gap-2';\r\n");
      out.write("        div.innerHTML = '<div class=\"input-group input-group-sm\" style=\"width: 140px;\">' +\r\n");
      out.write("            '<span class=\"input-group-text\"><i class=\"bi ' + iconVal + '\"></i></span>' +\r\n");
      out.write("            '<input type=\"text\" class=\"form-control\" value=\"' + escapeHtml(iconVal) + '\" onchange=\"updateCoreValue(' + idx + ', \\'icon\\', this.value)\" placeholder=\"Icon class\">' +\r\n");
      out.write("            '</div>' +\r\n");
      out.write("            '<input type=\"text\" class=\"form-control form-control-sm fw-semibold\" style=\"width: 220px;\" value=\"' + escapeHtml(titleVal) + '\" onchange=\"updateCoreValue(' + idx + ', \\'title\\', this.value)\" placeholder=\"Tiêu đề giá trị\">' +\r\n");
      out.write("            '<input type=\"text\" class=\"form-control form-control-sm flex-fill\" value=\"' + escapeHtml(descVal) + '\" onchange=\"updateCoreValue(' + idx + ', \\'desc\\', this.value)\" placeholder=\"Mô tả ngắn\">' +\r\n");
      out.write("            '<button type=\"button\" class=\"btn btn-outline-danger btn-sm\" onclick=\"removeCoreValue(' + idx + ')\" title=\"Xóa\"><i class=\"bi bi-trash\"></i></button>';\r\n");
      out.write("        container.appendChild(div);\r\n");
      out.write("    });\r\n");
      out.write("    syncJsonInputs();\r\n");
      out.write("}\r\n");
      out.write("\r\n");
      out.write("function addCoreValueItem() {\r\n");
      out.write("    coreValuesData.push({ icon: \"bi-star\", title: \"Giá trị mới\", desc: \"Mô tả giá trị cốt lõi...\" });\r\n");
      out.write("    renderCoreValuesList();\r\n");
      out.write("}\r\n");
      out.write("\r\n");
      out.write("function updateCoreValue(idx, field, val) {\r\n");
