      out.write("        coreValuesData[idx][field] = val;\r\n");
      out.write("        syncJsonInputs();\r\n");
      out.write("    }\r\n");
      out.write("}\r\n");
      out.write("\r\n");
      out.write("function removeCoreValue(idx) {\r\n");
      out.write("    coreValuesData.splice(idx, 1);\r\n");
      out.write("    renderCoreValuesList();\r\n");
      out.write("}\r\n");
      out.write("\r\n");
      out.write("// Render danh sách Đãi ngộ (Perks)\r\n");
      out.write("function renderPerksList() {\r\n");
      out.write("    const container = document.getElementById('perksContainer');\r\n");
      out.write("    container.innerHTML = '';\r\n");
      out.write("    perksData.forEach((item, idx) => {\r\n");
      out.write("        const iconVal = item.icon || 'bi-gift';\r\n");
      out.write("        const titleVal = item.title || '';\r\n");
      out.write("        const descVal = item.desc || '';\r\n");
      out.write("        const div = document.createElement('div');\r\n");
      out.write("        div.className = 'border rounded p-2 bg-light d-flex align-items-center gap-2';\r\n");
      out.write("        div.innerHTML = '<div class=\"input-group input-group-sm\" style=\"width: 140px;\">' +\r\n");
      out.write("            '<span class=\"input-group-text\"><i class=\"bi ' + iconVal + '\"></i></span>' +\r\n");
      out.write("            '<input type=\"text\" class=\"form-control\" value=\"' + escapeHtml(iconVal) + '\" onchange=\"updatePerk(' + idx + ', \\'icon\\', this.value)\" placeholder=\"Icon class\">' +\r\n");
      out.write("            '</div>' +\r\n");
      out.write("            '<input type=\"text\" class=\"form-control form-control-sm fw-semibold text-success\" style=\"width: 220px;\" value=\"' + escapeHtml(titleVal) + '\" onchange=\"updatePerk(' + idx + ', \\'title\\', this.value)\" placeholder=\"Tên quyền lợi\">' +\r\n");
      out.write("            '<input type=\"text\" class=\"form-control form-control-sm flex-fill\" value=\"' + escapeHtml(descVal) + '\" onchange=\"updatePerk(' + idx + ', \\'desc\\', this.value)\" placeholder=\"Mô tả chi tiết\">' +\r\n");
      out.write("            '<button type=\"button\" class=\"btn btn-outline-danger btn-sm\" onclick=\"removePerk(' + idx + ')\" title=\"Xóa\"><i class=\"bi bi-trash\"></i></button>';\r\n");
      out.write("        container.appendChild(div);\r\n");
      out.write("    });\r\n");
      out.write("    syncJsonInputs();\r\n");
      out.write("}\r\n");
      out.write("\r\n");
      out.write("function addPerkItem() {\r\n");
      out.write("    perksData.push({ icon: \"bi-gift\", title: \"Quyền lợi mới\", desc: \"Chính sách đãi ngộ chi tiết...\" });\r\n");
      out.write("    renderPerksList();\r\n");
      out.write("}\r\n");
      out.write("\r\n");
      out.write("function updatePerk(idx, field, val) {\r\n");
      out.write("    if (perksData[idx]) {\r\n");
      out.write("        perksData[idx][field] = val;\r\n");
      out.write("        syncJsonInputs();\r\n");
      out.write("    }\r\n");
      out.write("}\r\n");
