      out.write("    renderPerksList();\r\n");
      out.write("}\r\n");
      out.write("\r\n");
      out.write("// Render Bộ sưu tập ảnh (Gallery)\r\n");
      out.write("function renderGalleryList() {\r\n");
      out.write("    const container = document.getElementById('galleryContainer');\r\n");
      out.write("    container.innerHTML = '';\r\n");
      out.write("    galleryData.forEach((url, idx) => {\r\n");
      out.write("        const col = document.createElement('div');\r\n");
      out.write("        col.className = 'col-12 col-md-4';\r\n");
      out.write("        col.innerHTML = '<div class=\"card border shadow-none h-100\">' +\r\n");
      out.write("            '<div class=\"position-relative\" style=\"height: 140px; overflow: hidden;\">' +\r\n");
      out.write("            '<img src=\"' + url + '\" class=\"card-img-top\" style=\"width: 100%; height: 100%; object-fit: cover;\" onerror=\"this.src=\\'https://images.unsplash.com/photo-1522071820081-009f0129c71c?auto=format&fit=crop&w=800&q=80\\'\">' +\r\n");
      out.write("            '<button type=\"button\" class=\"btn btn-danger btn-sm position-absolute top-0 end-0 m-1 py-0 px-2\" onclick=\"removeGalleryImage(' + idx + ')\" title=\"Xóa ảnh\">&times;</button>' +\r\n");
      out.write("            '</div>' +\r\n");
      out.write("            '<div class=\"p-2 bg-light\">' +\r\n");
      out.write("            '<input type=\"text\" class=\"form-control form-control-sm text-xs font-monospace\" value=\"' + escapeHtml(url) + '\" onchange=\"updateGalleryImage(' + idx + ', this.value)\" placeholder=\"URL ảnh...\">' +\r\n");
      out.write("            '</div></div>';\r\n");
      out.write("        container.appendChild(col);\r\n");
      out.write("    });\r\n");
      out.write("    syncJsonInputs();\r\n");
      out.write("}\r\n");
      out.write("\r\n");
      out.write("function addGalleryImageItem() {\r\n");
      out.write("    const defaultImg = \"https://images.unsplash.com/photo-1522071820081-009f0129c71c?auto=format&fit=crop&w=800&q=80\";\r\n");
      out.write("    galleryData.push(defaultImg);\r\n");
      out.write("    renderGalleryList();\r\n");
      out.write("}\r\n");
      out.write("\r\n");
      out.write("function updateGalleryImage(idx, val) {\r\n");
      out.write("    if (galleryData[idx] !== undefined) {\r\n");
      out.write("        galleryData[idx] = val;\r\n");
      out.write("        syncJsonInputs();\r\n");
      out.write("    }\r\n");
      out.write("}\r\n");
      out.write("\r\n");
      out.write("function removeGalleryImage(idx) {\r\n");
      out.write("    galleryData.splice(idx, 1);\r\n");
      out.write("    renderGalleryList();\r\n");
      out.write("}\r\n");
      out.write("\r\n");
      out.write("function syncJsonInputs() {\r\n");
      out.write("    document.getElementById('inputCoreValues').value = JSON.stringify(coreValuesData);\r\n");
      out.write("    document.getElementById('inputPerks').value = JSON.stringify(perksData);\r\n");
      out.write("    document.getElementById('inputGalleryUrls').value = JSON.stringify(galleryData);\r\n");
      out.write("}\r\n");
      out.write("\r\n");
      out.write("function escapeHtml(text) {\r\n");
      out.write("    if (!text) return '';\r\n");
      out.write("    return String(text).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\"/g, '&quot;');\r\n");
      out.write("}\r\n");
      out.write("\r\n");
      out.write("// Xử lý xem trước ảnh khi chọn file từ máy tính\r\n");
      out.write("function handleLocalImagePreview(input, imgElementId, urlInputId) {\r\n");
      out.write("    if (input.files && input.files[0]) {\r\n");
      out.write("        const file = input.files[0];\r\n");
      out.write("        const reader = new FileReader();\r\n");
      out.write("        reader.onload = function (e) {\r\n");
      out.write("            document.getElementById(imgElementId).src = e.target.result;\r\n");
      out.write("            if (urlInputId === 'editLogoUrl') {\r\n");
      out.write("                document.getElementById('miniLogo').src = e.target.result;\r\n");
      out.write("            } else if (urlInputId === 'editBannerUrl') {\r\n");
      out.write("                document.getElementById('miniBanner').style.backgroundImage = 'url(\\'' + e.target.result + '\\')';\r\n");
      out.write("            }\r\n");
      out.write("        };\r\n");
      out.write("        reader.readAsDataURL(file);\r\n");
      out.write("    }\r\n");
      out.write("}\r\n");
      out.write("\r\n");
      out.write("// Đồng bộ theo thời gian thực vào Mini Preview bên phải\r\n");
      out.write("function bindRealTimeMiniPreview() {\r\n");
      out.write("    const bindMap = [\r\n");
      out.write("        { src: 'editCompanyName', target: 'pvHeroBrand' },\r\n");
      out.write("        { src: 'editBrandName', target: 'miniBrandName' },\r\n");
      out.write("        { src: 'editSlogan', target: 'miniSlogan' },\r\n");
      out.write("        { src: 'editTagline', target: 'miniTagline' },\r\n");
      out.write("        { src: 'editOverview', target: 'miniOverview' }\r\n");
      out.write("    ];\r\n");
      out.write("\r\n");
      out.write("    bindMap.forEach(item => {\r\n");
      out.write("        const el = document.getElementById(item.src);\r\n");
      out.write("        if (el) {\r\n");
      out.write("            el.addEventListener('input', function () {\r\n");
      out.write("                const target = document.getElementById(item.target);\r\n");
      out.write("                if (target) target.innerText = this.value;\r\n");
      out.write("            });\r\n");
      out.write("        }\r\n");
      out.write("    });\r\n");
      out.write("}\r\n");
      out.write("\r\n");
      out.write("function updateBadgeStatus(val) {\r\n");
      out.write("    const badge = document.getElementById('badgeStatusLabel');\r\n");
      out.write("    if (val === 'PUBLISHED') {\r\n");
      out.write("        badge.className = 'badge bg-success-subtle text-success border border-success-subtle';\r\n");
      out.write("        badge.innerText = 'Đã xuất bản';\r\n");
      out.write("    } else {\r\n");
      out.write("        badge.className = 'badge bg-warning-subtle text-warning border border-warning-subtle';\r\n");
      out.write("        badge.innerText = 'Bản nháp';\r\n");
      out.write("    }\r\n");
      out.write("}\r\n");
      out.write("\r\n");
      out.write("// MỞ MODAL XEM TRƯỚC ĐÚNG NHƯ GIAO DIỆN CÔNG KHAI (TIÊU CHÍ BẮT BUỘC 2)\r\n");
      out.write("function openLivePreviewModal() {\r\n");
      out.write("    syncJsonInputs();\r\n");
      out.write("\r\n");
      out.write("    // 1. Đồng bộ thông tin thương hiệu\r\n");
      out.write("    const compName = document.getElementById('editCompanyName').value || 'Tập đoàn Công nghệ IRMS';\r\n");
      out.write("    const brandName = document.getElementById('editBrandName').value || compName;\r\n");
      out.write("    const slogan = document.getElementById('editSlogan').value || 'Tiên phong công nghệ - Kiến tạo tương lai';\r\n");
      out.write("    const tagline = document.getElementById('editTagline').value || 'Nơi tài năng hội tụ';\r\n");
      out.write("    const logoUrl = document.getElementById('previewLogoImg').src;\r\n");
      out.write("    const bannerUrl = document.getElementById('previewBannerImg').src;\r\n");
      out.write("\r\n");
      out.write("    document.getElementById('pvNavLogo').src = logoUrl;\r\n");
      out.write("    document.getElementById('pvNavBrand').innerText = brandName;\r\n");
      out.write("    document.getElementById('pvHeroBrand').innerText = compName;\r\n");
      out.write("    document.getElementById('pvHeroSlogan').innerText = slogan;\r\n");
      out.write("    document.getElementById('pvHeroTagline').innerText = tagline;\r\n");
      out.write("    document.getElementById('pvHeroSection').style.backgroundImage = 'linear-gradient(rgba(15, 23, 42, 0.75), rgba(15, 23, 42, 0.75)), url(\\'' + bannerUrl + '\\')';\r\n");
      out.write("\r\n");
      out.write("    // 2. Đồng bộ nội dung giới thiệu\r\n");
      out.write("    document.getElementById('pvOverviewText').innerText = document.getElementById('editOverview').value || 'Đang cập nhật nội dung giới thiệu...';\r\n");
      out.write("    document.getElementById('pvMissionText').innerText = document.getElementById('editMission').value || 'Đang cập nhật sứ mệnh...';\r\n");
      out.write("    document.getElementById('pvVisionText').innerText = document.getElementById('editVision').value || 'Đang cập nhật tầm nhìn...';\r\n");
      out.write("    document.getElementById('pvCultureText').innerText = document.getElementById('editCultureDesc').value || 'Đang cập nhật văn hóa...';\r\n");
      out.write("    document.getElementById('pvCultureImg').src = bannerUrl;\r\n");
      out.write("\r\n");
      out.write("    // 3. Render Giá trị cốt lõi lên Preview\r\n");
      out.write("    const valuesGrid = document.getElementById('pvCoreValuesGrid');\r\n");
      out.write("    valuesGrid.innerHTML = '';\r\n");
      out.write("    coreValuesData.forEach(v => {\r\n");
      out.write("        const iconVal = v.icon || 'bi-star';\r\n");
      out.write("        const col = document.createElement('div');\r\n");
      out.write("        col.className = 'col-12 col-md-4';\r\n");
      out.write("        col.innerHTML = '<div class=\"card h-100 border-0 shadow-sm p-4 rounded-4 text-center\">' +\r\n");
      out.write("            '<div class=\"rounded-circle bg-primary-subtle text-primary mx-auto mb-3 d-flex align-items-center justify-content-center\" style=\"width: 56px; height: 56px;\">' +\r\n");
      out.write("            '<i class=\"bi ' + iconVal + ' fs-4\"></i>' +\r\n");
      out.write("            '</div>' +\r\n");
      out.write("            '<h6 class=\"fw-bold text-dark\">' + escapeHtml(v.title || '') + '</h6>' +\r\n");
      out.write("            '<p class=\"text-muted small mb-0\">' + escapeHtml(v.desc || '') + '</p>' +\r\n");
      out.write("            '</div>';\r\n");
      out.write("        valuesGrid.appendChild(col);\r\n");
      out.write("    });\r\n");
      out.write("\r\n");
      out.write("    // 4. Render Chế độ đãi ngộ lên Preview\r\n");
      out.write("    const perksGrid = document.getElementById('pvPerksGrid');\r\n");
      out.write("    perksGrid.innerHTML = '';\r\n");
      out.write("    perksData.forEach(p => {\r\n");
      out.write("        const iconVal = p.icon || 'bi-gift';\r\n");
      out.write("        const col = document.createElement('div');\r\n");
      out.write("        col.className = 'col-12 col-md-6 col-lg-3';\r\n");
      out.write("        col.innerHTML = '<div class=\"card h-100 border border-success-subtle bg-white p-3 rounded-3\">' +\r\n");
      out.write("            '<div class=\"d-flex align-items-center gap-2 mb-2\">' +\r\n");
