      out.write("        col.className = 'col-12 col-md-4';\r\n");
      out.write("        col.innerHTML = '<div class=\"rounded-3 overflow-hidden shadow-sm h-100\" style=\"min-height: 180px;\">' +\r\n");
      out.write("            '<img src=\"' + img + '\" class=\"img-fluid w-100 h-100\" style=\"object-fit: cover;\" onerror=\"this.src=\\'https://images.unsplash.com/photo-1522071820081-009f0129c71c?auto=format&fit=crop&w=800&q=80\\'\">' +\r\n");
